const withHistory = (component) => (msg, next) => {
  const prev = JSON.parse(msg.headers?.history ?? '[]');   // [{ name, ts }]
  msg.headers = { ...msg.headers, history: JSON.stringify([...prev, { name: component, ts: Date.now() }]) };
  return next(msg);
};
